#!/bin/sh
# Generated from cleanup.py; no data migration.
set -eu
umask 077
export PATH="${PATH:+$PATH:}/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/data/docker"
worker=$(mktemp /tmp/minas-manager.XXXXXXXX)
trap 'rm -f -- "$worker"' EXIT
cat > "$worker" <<'MINAS_LAYOUT_PY'
