d-%H%M%S)-$$"\n    mkdir -p "$NAS_BACKUP"\n    chmod 0700 "$NAS_BACKUP"\n    nas_log "停止所选用户的插件并备份配置……"\n    plugincenter -u "$NAS_USER" -p "$NAS_PLUGIN" disable >/dev/null 2>&1 || true\n    if [ -x "$NAS_HOME/scripts/control" ]; then\n        PLUG_USER="$NAS_USER" PLUG_NAME="$NAS_PLUGIN" PLUG_HOME_DIR="$NAS_HOME" PLUG_SRC_DIR="$NAS_SRC" \\\n            "$NAS_HOME/scripts/control" disable || nas_fail "插件停止失败，保留安装文件，请检查服务状态后重试。"\n    fi\n    for nas_data in etc var INFO; do\n        if [ -e "$NAS_HOME/$nas_data" ]; then cp -a "$NAS_HOME/$nas_data" "$NAS_BACKUP/"; fi\n    done\n    if [ -f /data/minas/plugins/recovery/recovery.py ]; then\n        python3 -B /data/minas/plugins/recovery/recovery.py forget --user "$NAS_USER" --plugin "$NAS_PLUGIN" || nas_fail "取消恢复登记失败"\n    fi\n    nas_remove_entry\n    rm -f "/etc/cron.d/downloadcenter-$NAS_USER"\n    rm -f "$NAS_WEB_ROOT/$NAS_USER/$NAS_PLUGIN"\n    # Paths were checked in full by nas_check_user; repeat immediately before removal.\n    nas_pool_path "$NAS_SRC" pluginsrc; nas_pool_path "$NAS_TMP" plugintmp\n    rm -rf "$NAS_SRC" "$NAS_TMP" "$NAS_HOME"\n    if ! nas_other_users; then\n        rm -f "/data/plugin/www/icon/$NAS_PLUGIN.icon"\n    fi\n    systemctl reload crond.service >/dev/null 2>&1 || true\n    nas_log "$NAS_USER 的$NAS_LABEL已卸载。"\n    nas_log "配置及记录备份：$NAS_BACKUP"\n    nas_log "$UNINSTALL_NOTE"\n}\n# Direct read-only entry points used by the frontend over SSH.\ncase "${1:-}" in\n    --scan)\n        set -eu\n        [ "$#" = 3 ] || nas_fail "扫描参数错误。"\n        case "$3" in install|uninstall) ;; *) nas_fail "无效操作。";; esac\n        nas_scan "$2" "$3";;\n    --check)\n        set -eu\n        nas_metadata "$2"; NAS_ACTION=$3; shift 3\n        case "$NAS_ACTION" in install|uninstall) ;; *) nas_fail "无效操作。";; esac\n        nas_environment\n        for nas_selected in "$@"; do nas_check_user "$nas_selected"; done;;\nesac\nnas_uninstall "${1:-}"\n', 'mediaeditor': '#!/bin/sh\nset -eu\nPLUGIN_NAME=mediaeditor\nPLUGIN_LABEL=\'影视编辑\'\nPLUGIN_VERSION=1.1.8\nUNINSTALL_NOTE=\'不修改官方影视库，受保护的编辑备份与历史保留在 /data/minas/plugins/data/<账号>/mediaeditor/protected/。\'\n#!/bin/sh\n# Shared NAS checks and uninstall workflow; identical in all standalone packages.\nnas_fail() { printf \'[错误] %s\\n\' "$*" >&2; exit 1; }\nnas_log() { printf \'[信息] %s\\n\' "$*"; }\nnas_valid_user() {\n    case "$1" in u*) ;; *) return 1;; esac\n    case "${1#u}" in \'\'|*[!0-9]*) return 1;; esac\n}\nnas_metadata() {\n    NAS_PLUGIN=$1\n    case "$NAS_PLUGIN" in\n        mihomo) NAS_LABEL=Mihomo;;\n        dockermanager) NAS_LABEL=docker;;\n        quickshare) NAS_LABEL=文件快传;;\n        mediaeditor) NAS_LABEL=影视编辑;;\n        *) nas_fail "无效插件名称。";;\n    esac\n}\nnas_require() {\n    for nas_cmd in "$@"; do command -v "$nas_cmd" >/dev/null 2>&1 || nas_fail "NAS 缺少命令：$nas_cmd"; done\n}\nnas_environment() {\n    [ "$(id -u)" = 0 ] || nas_fail "请以 root 身份在小米智能存储上执行。"\n    [ -f /etc/config/plugin ] || nas_fail "未检测到小米智能存储配置。"\n    nas_require jq plugincenter sort readlink mountpoint flock\n}\nnas_is_installed() {\n    [ -d "/home/$1/plugin/$NAS_PLUGIN" ] || [ -L "/home/$1/plugin/$NAS_PLUGIN" ] ||\n        { [ -f "/data/plugin/$1.list" ] && jq -e --arg p "$NAS_PLUGIN" \'.[$p].install == true\' "/data/plugin/$1.list" >/dev/null 2>&1; }\n}\nnas_scan() {\n    nas_metadata "$1"; nas_action=$2\n    nas_environment\n    # Include accounts whose registration or home exists; never rely on find following symlinks.\n    {\n        for nas_item in /data/plugin/u*.list; do\n            [ -f "$nas_item" ] || continue\n            nas_candidate=${nas_item##*/}; nas_candidate=${nas_candidate%.list}\n            nas_valid_user "$nas_candidate" && printf \'%s\\n\' "$nas_candidate"\n        done\n        for nas_item in /home/u*; do\n            [ -d "$nas_item" ] || continue\n            nas_candidate=${nas_item##*/}\n            nas_valid_user "$nas_candidate" && printf \'%s\\n\' "$nas_candidate"\n        done\n    } | LC_ALL=C sort -u | while IFS= read -r nas_candidate; do\n        nas_state=available\n        if nas_is_installed "$nas_candidate"; then nas_state=installed; fi\n        if [ "$nas_action" = uninstall ]; then\n            [ "$nas_state" = installed ] || continue\n        else\n            id "$nas_candidate" >/dev/null 2>&1 || continue\n            [ -d "/home/$nas_candidate" ] && [ -f "/data/plugin/$nas_candidate.list" ] || continue\n        fi\n        printf \'%s\\t%s\\n\' "$nas_candidate" "$nas_state"\n    done\n}\nnas_pool_path() {\n    # Strictly validate the whole path before creating, moving or removing anything.\n    nas_path=$1; nas_kind=$2\n    nas_pool=${nas_path#/nas/}; nas_pool=${nas_pool%%/*}\n    case "$nas_pool" in pool*) ;; *) nas_fail "异常存储池路径：$nas_path";; esac\n    case "${nas_pool#pool}" in \'\'|*[!0-9]*) nas_fail "异常存储池路径：$nas_path";; esac\n    [ "$nas_path" = "/nas/$nas_pool/$NAS_USER/plugin/$nas_kind/$NAS_PLUGIN" ] || nas_fail "异常插件路径：$nas_path"\n    mountpoint -q "/nas/$nas_pool" || nas_fail "存储池 /nas/$nas_pool 尚未挂载，请恢复硬盘挂载后重试。"\n    [ -d "/nas/$nas_pool/$NAS_USER" ] || nas_fail "存储池内不存在用户 $NAS_USER。"\n    nas_real=$(readlink -f "$nas_path" 2>/dev/null || true)\n    [ -z "$nas_real" ] || [ "$nas_real" = "$nas_path" ] || nas_fail "插件路径重定向到其他位置：$nas_path"\n}\nnas_check_user() {\n    NAS_USER=$1\n    nas_valid_user "$NAS_USER" || nas_fail "无效用户：$NAS_USER（应为 u 后接数字）"\n    [ -d "/home/$NAS_USER" ] || nas_fail "用户主目录不存在：$NAS_USER"\n    id "$NAS_USER" >/dev/null 2>&1 || nas_fail "系统账户不存在：$NAS_USER"\n    NAS_HOME="/home/$NAS_USER/plugin/$NAS_PLUGIN"\n    [ ! -L "$NAS_HOME" ] || nas_fail "插件主目录不能为符号链接：$NAS_HOME"\n    NAS_LIST="/data/plugin/$NAS_USER.list"\n    if [ -f "$NAS_LIST" ]; then\n        jq -e \'type == "object"\' "$NAS_LIST" >/dev/null 2>&1 || nas_fail "插件清单损坏：$NAS_LIST"\n    elif [ "$NAS_ACTION" = install ]; then\n        nas_fail "插件清单不存在：$NAS_LIST"\n    fi\n    NAS_SRC="/nas/pool0/$NAS_USER/plugin/pluginsrc/$NAS_PLUGIN"\n    NAS_TMP="/nas/pool0/$NAS_USER/plugin/plugintmp/$NAS_PLUGIN"\n    if [ -L "$NAS_HOME/src" ]; then NAS_SRC=$(readlink "$NAS_HOME/src"); fi\n    if [ -L "$NAS_HOME/tmp" ]; then NAS_TMP=$(readlink "$NAS_HOME/tmp"); else NAS_TMP="${NAS_SRC%/pluginsrc/*}/plugintmp/$NAS_PLUGIN"; fi\n    nas_pool_path "$NAS_SRC" pluginsrc\n    nas_pool_path "$NAS_TMP" plugintmp\n    if [ "$NAS_ACTION" = uninstall ]; then nas_is_installed "$NAS_USER" || nas_fail "$NAS_USER 尚未安装$NAS_LABEL。"; fi\n    NAS_WEB_ROOT=$(jq -r \'.settings.nginx_plugin // "/data/plugin/www"\' /etc/config/plugin)\n    case "$NAS_WEB_ROOT" in /*) ;; *) nas_fail "插件网页根目录配置无效。";; esac\n}\nnas_prepare() {\n    NAS_ACTION=$1; nas_metadata "$PLUGIN_NAME"\n    nas_environment\n    [ -n "${2:-}" ] || nas_fail "请显式指定插件用户；推荐运行 manage.sh install 或 manage.sh uninstall。"\n    # Serialize installer operations across users and plugins that share helpers and icons.\n    exec 7>/data/plugin/.local-plugin-installer.lock\n    flock -w 60 -x 7 || nas_fail "另一个安装或卸载任务仍在执行，请稍后重试。"\n    trap \'flock -u 7 2>/dev/null || true\' 0\n    nas_check_user "$2"\n    if [ "$NAS_ACTION" = install ]; then\n        python3 -B "$INSTALLER_DIR/$PLUGIN_NAME/installer/recovery/recovery.py" --help >/dev/null\n        python3 -B - "$INSTALLER_DIR/$PLUGIN_NAME/installer/recovery/recovery.py" "$NAS_USER" "$NAS_PLUGIN" "$NAS_HOME" <<\'MINAS_DIRECT_STATE\'\nimport importlib.util,os,pwd,sys\nfrom pathlib import Path\nspec=importlib.util.spec_from_file_location(\'direct_state\',sys.argv[1]);r=importlib.util.module_from_spec(spec);spec.loader.exec_module(r)\nuser,plugin,home=sys.argv[2],sys.argv[3],Path(sys.argv[4]);owner=pwd.getpwnam(user)\nr.ensure_data_layout()\nr.plain(home);home.mkdir(mode=0o700,parents=True,exist_ok=True)\nr.persist_state(user,plugin,home,None,(owner.pw_uid,owner.pw_gid),False)\nMINAS_DIRECT_STATE\n    fi\n    nas_log "$NAS_LABEL：已校验用户 $NAS_USER、插件目录和存储池。"\n}\nnas_remove_entry() {\n    [ -f "$NAS_LIST" ] || return 0\n    exec 9>"/data/plugin/.$NAS_USER.plugins.lock"\n    flock -x 9\n    nas_next="$NAS_LIST.$NAS_PLUGIN-uninstall.$$"\n    cp -p "$NAS_LIST" "$NAS_BACKUP/plugin-list.json"\n    jq --arg p "$NAS_PLUGIN" \'del(.[$p])\' "$NAS_LIST" > "$nas_next"\n    chmod --reference="$NAS_LIST" "$nas_next"\n    chown --reference="$NAS_LIST" "$nas_next"\n    mv -f "$nas_next" "$NAS_LIST"\n    flock -u 9\n}\nnas_other_users() {\n    for nas_d in /home/u*/plugin/"$NAS_PLUGIN"; do\n        [ ! -d "$nas_d" ] && [ ! -L "$nas_d" ] || return 0\n    done\n    for nas_f in /data/plugin/u*.list; do\n        [ -f "$nas_f" ] || continue\n        # If another user\'s registry is unreadable, preserve shared files.\n        jq empty "$nas_f" >/dev/null 2>&1 || return 0\n        if jq -e --arg p "$NAS_PLUGIN" \'.[$p].install == true\' "$nas_f" >/dev/null 2>&1; then return 0; fi\n    done\n    return 1\n}\nnas_uninstall() {\n    nas_prepare uninstall "${1:-}"\n    nas_require cp date chmod chown rm\n    NAS_BACKUP="/home/$NAS_USER/plugin/.reserve/$NAS_PLUGIN/$(date +%Y%m%d-%H%M%S)-$$"\n    mkdir -p "$NAS_BACKUP"\n    chmod 0700 "$NAS_BACKUP"\n    nas_log "停止所选用户的插件并备份配置……"\n    if [ -f /data/minas/privileged/component_admin.py ]; then\n        python3 /data/minas/privileged/component_admin.py remove --plugin "$NAS_PLUGIN" --user "$NAS_USER" || nas_fail "公共权限模块卸载失败"\n    fi\n    plugincenter -u "$NAS_USER" -p "$NAS_PLUGIN" disable >/dev/null 2>&1 || true\n    if [ -x "$NAS_HOME/scripts/control" ]; then\n        PLUG_USER="$NAS_USER" PLUG_NAME="$NAS_PLUGIN" PLUG_HOME_DIR="$NAS_HOME" PLUG_SRC_DIR="$NAS_SRC" \\\n            "$NAS_HOME/scripts/control" disable || nas_fail "插件停止失败，保留安装文件，请检查服务状态后重试。"\n    fi\n    for nas_data in etc var INFO; do\n        if [ -e "$NAS_HOME/$nas_data" ]; then cp -a "$NAS_HOME/$nas_data" "$NAS_BACKUP/"; fi\n    done\n    if [ -f /data/minas/plugins/recovery/recovery.py ]; then\n        python3 -B /data/minas/plugins/recovery/recovery.py forget --user "$NAS_USER" --plugin "$NAS_PLUGIN" || nas_fail "取消恢复登记失败"\n    fi\n    nas_remove_entry\n    case "$NAS_PLUGIN" in\n        mediaeditor)\n            rm -f "/etc/sudoers.d/mediaeditor-$NAS_USER";;\n    esac\n    rm -f "$NAS_WEB_ROOT/$NAS_USER/$NAS_PLUGIN"\n    # Paths were checked in full by nas_check_user; repeat immediately before removal.\n    nas_pool_path "$NAS_SRC" pluginsrc; nas_pool_path "$NAS_TMP" plugintmp\n    rm -rf "$NAS_SRC" "$NAS_TMP" "$NAS_HOME"\n    if ! nas_other_users; then\n        rm -f "/data/plugin/www/icon/$NAS_PLUGIN.icon"\n    fi\n    systemctl reload crond.service >/dev/null 2>&1 || true\n    nas_log "$NAS_USER 的$NAS_LABEL已卸载。"\n    nas_log "配置及记录备份：$NAS_BACKUP"\n    nas_log "$UNINSTALL_NOTE"\n}\n# Direct read-only entry points used by the frontend over SSH.\ncase "${1:-}" in\n    --scan)\n        set -eu\n        [ "$#" = 3 ] || nas_fail "扫描参数错误。"\n        case "$3" in install|uninstall) ;; *) nas_fail "无效操作。";; esac\n        nas_scan "$2" "$3";;\n    --check)\n        set -eu\n        nas_metadata "$2"; NAS_ACTION=$3; shift 3\n        case "$NAS_ACTION" in install|uninstall) ;; *) nas_fail "无效操作。";; esac\n        nas_environment\n        for nas_selected in "$@"; do nas_check_user "$nas_selected"; done;;\nesac\nnas_uninstall "${1:-}"\n'}
SSH_INSTALLER = '#!/usr/bin/env python3\n"""Standard NAS registration plus a narrowly scoped root-owned SSH helper."""\nimport contextlib\nimport fcntl\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport pwd\nimport re\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\nimport time\n\nPLUGIN, VERSION = \'sshrecovery\', \'1.1.33\'\nSYSTEM = Path(\'/data/minas/privileged\')\n\ndef initialize_layout(payload):\n    """Use the already-bundled initializer; no separate layout program."""\n    import importlib.util\n    spec=importlib.util.spec_from_file_location(\'installer_layout\',payload/\'installer/recovery/recovery.py\')\n    recovery=importlib.util.module_from_spec(spec);spec.loader.exec_module(recovery)\n    recovery.ensure_data_layout()\n    return recovery\n\n\ndef system_install(user, payload):\n    host=Path(\'/etc/dropbear/dropbear_rsa_host_key\')\n    if host.exists():\n        require(not host.is_symlink() and host.stat().st_uid==0 and host.stat().st_size<=65536,\'主机密钥异常\')\n    result=subprocess.run([sys.executable,\'-B\',str(payload/\'installer/common/component_admin.py\'),\'install\',\n                           \'--plugin\',PLUGIN,\'--user\',user,\'--payload\',str(payload),\'--plugin-version\',VERSION],\n                          capture_output=True,timeout=120)\n    require(result.returncode == 0, \'公共权限组件安装失败：\' + result.stderr.decode(\'utf-8\', errors=\'replace\').strip())\n    report=json.loads(result.stdout)\n    saved=SYSTEM/\'modules/sshrecovery/var/host/dropbear_rsa_host_key\'\n    if host.is_file() and not saved.exists():atomic(saved,host.read_bytes(),0o400,(0,0))\n    # Update only already-installed recovery programs. A fresh plugin install\n    # must not install boot jobs or change the current SSH enable/running state.\n    refresh=subprocess.run([sys.executable,\'-B\',str(SYSTEM/\'modules/sshrecovery/ssh-recovery-helper\'),\'--refresh-installed\'],\n                           capture_output=True,timeout=30)\n    require(refresh.returncode==0,\'同步已安装的 SSH 恢复程序失败：\'+refresh.stdout.decode(\'utf-8\',errors=\'replace\').strip())\n    report[\'sshTools\']=json.loads(refresh.stdout)\n    return report\n\ndef system_remove(user):\n    subprocess.run([sys.executable,\'-B\',str(SYSTEM/\'component_admin.py\'),\'remove\',\n                    \'--plugin\',PLUGIN,\'--user\',user],check=True,timeout=120)\n\ndef require(condition, message):\n    if not condition: raise RuntimeError(message)\n\ndef read_json(path):\n    result = json.loads(path.read_text())\n    require(isinstance(result, dict), \'JSON 配置必须为对象：\' + str(path))\n    return result\n\ndef installed(user):\n    home = Path(\'/home\') / user / \'plugin\' / PLUGIN\n    if home.exists(): return True\n    registry = Path(\'/data/plugin\') / (user + \'.list\')\n    return registry.exists() and bool(read_json(registry).get(PLUGIN, {}).get(\'install\'))\n\ndef users(action):\n    candidates = {p.name for p in Path(\'/home\').glob(\'u*\')} | {p.stem for p in Path(\'/data/plugin\').glob(\'u*.list\')}\n    result = []\n    for user in sorted(candidates):\n        if not re.fullmatch(\'u[0-9]+\', user): continue\n        try: pwd.getpwnam(user)\n        except KeyError: continue\n        state = installed(user)\n        if action == \'uninstall\' and not state: continue\n        if action == \'install\' and not (Path(\'/data/plugin\') / (user + \'.list\')).is_file(): continue\n        result.append((user, \'installed\' if state else \'available\'))\n    return result\n\ndef paths(user, action):\n    require(bool(re.fullmatch(\'u[0-9]+\', user)), \'无效用户\')\n    account = pwd.getpwnam(user)\n    home = Path(\'/home\') / user / \'plugin\' / PLUGIN\n    require(not home.is_symlink(), \'插件主目录不能是符号链接\')\n    src = Path(os.readlink(home / \'src\')) if (home / \'src\').is_symlink() else Path(\'/nas/pool0\') / user / \'plugin/pluginsrc\' / PLUGIN\n    match = re.fullmatch(\'/nas/(pool[0-9]+)/\' + user + \'/plugin/pluginsrc/sshrecovery\', str(src))\n    require(bool(match), \'插件源码路径异常\')\n    pool = Path(\'/nas\') / match[1]\n    require(os.path.ismount(pool), \'存储池尚未挂载，请恢复后重试\')\n    require((pool / user).is_dir(), \'存储池用户目录不存在\')\n    tmp = pool / user / \'plugin/plugintmp\' / PLUGIN\n    for path in (home, src, tmp): require(path.resolve() == path, \'路径存在意外重定向：\' + str(path))\n    for name, expected in ((\'src\', src), (\'tmp\', tmp)):\n        link = home / name\n        require(not link.exists() or link.is_symlink(), \'插件目录异常：\' + str(link))\n        if link.is_symlink(): require(Path(os.readlink(link)) == expected, \'插件链接目标不符\')\n    registry = Path(\'/data/plugin\') / (user + \'.list\')\n    require(registry.is_file() and not registry.is_symlink(), \'用户插件清单不存在或异常\')\n    read_json(registry)\n    web_root = Path(read_json(Path(\'/etc/config/plugin\')).get(\'settings\', {}).get(\'nginx_plugin\', \'/data/plugin/www\'))\n    require(web_root.is_absolute(), \'网页根目录必须是绝对路径\')\n    web = web_root / user / PLUGIN\n    require(not web.exists() or web.is_symlink(), \'网页入口已被其他文件占用\')\n    if web.is_symlink(): require(web.resolve() == src / \'ui\', \'网页入口目标异常\')\n    for name in (\'var\',\'etc\',\'scripts\',\'INFO\'):\n        node = home/name\n        allowed = name in (\'var\',\'etc\') and node.is_symlink() and os.readlink(node) == \'/data/minas/plugins/data/\' + user + \'/\' + PLUGIN + \'/\' + name\n        require(not node.is_symlink() or allowed, \'插件配置路径链接异常\')\n    if action == \'uninstall\': require(installed(user), \'该用户尚未安装SSH 恢复\')\n    return dict(user=user, uid=account.pw_uid, gid=account.pw_gid, home=home, src=src, tmp=tmp, registry=registry, web=web)\n\ndef atomic(path, content, mode=0o644, owner=None):\n    fd, name = tempfile.mkstemp(prefix=\'.sshrecovery-\', dir=path.parent)\n    try:\n        with os.fdopen(fd, \'wb\') as out:\n            out.write(content); out.flush(); os.fsync(out.fileno()); os.fchmod(out.fileno(), mode)\n            if owner: os.fchown(out.fileno(), *owner)\n        os.replace(name, path)\n    finally:\n        if os.path.exists(name): os.unlink(name)\n\ndef encoded(value): return (json.dumps(value, ensure_ascii=False, indent=2) + \'\\n\').encode()\n\ndef abstract(src):\n    content = \'\'.join(hashlib.sha256(p.read_bytes()).hexdigest() + \'\\n\' for p in sorted(src.rglob(\'*\')) if p.is_file() and not p.is_symlink())\n    return hashlib.sha256(content.encode()).hexdigest()\n\n\ndef install_icon(payload, icon):\n    png=(payload/\'src/ui/icon.png\').read_bytes()\n    require(png[:8]==b\'\\x89PNG\\r\\n\\x1a\\n\' and png[16:24]==(300).to_bytes(4,\'big\')*2, \'安装包图标必须为 300×300 PNG\')\n    atomic(icon,png,0o644)\n\ndef install(p, payload):\n    home, src, tmp, registry, web = (p[k] for k in (\'home\', \'src\', \'tmp\', \'registry\', \'web\'))\n    owner = (p[\'uid\'], p[\'gid\'])\n    for name in (\'src/ui\', \'scripts\',\'installer/common\'): require((payload / name).is_dir(), \'安装包缺少 \' + name)\n    old_registry = registry.read_bytes()\n    previous_info = (home / \'INFO\').read_bytes() if (home / \'INFO\').is_file() else None\n    new_home, new_tmp = not home.exists(), not tmp.exists()\n    for directory in (home, src.parent, tmp, web.parent, Path(\'/data/plugin/www/icon\')): directory.mkdir(parents=True, exist_ok=True)\n    stage = Path(tempfile.mkdtemp(prefix=\'.sshrecovery-new-\', dir=src.parent))\n    backup = Path(tempfile.mkdtemp(prefix=\'.sshrecovery-old-\', dir=src.parent))\n    previous_src, control = backup / \'src\', home / \'scripts/control\'\n    previous_control = control.read_bytes() if control.is_file() else None\n    switched, src_moved = False, False\n    icon = Path(\'/data/plugin/www/icon/sshrecovery.icon\')\n    old_icon = icon.read_bytes() if icon.exists() else None\n    web_existed = web.is_symlink()\n    try:\n        for name in (\'files\',\'ui\'): shutil.copytree(payload / \'src\' / name, stage / name)\n        for path in stage.rglob(\'*\'):\n            require(not path.is_symlink(), \'安装包不允许符号链接\')\n            os.chown(path, *owner); path.chmod(0o755 if path.is_dir() or path.suffix == \'.cgi\' else 0o644)\n        os.chown(stage, *owner); stage.chmod(0o700)\n        if src.exists(): os.replace(src, previous_src); src_moved = True\n        os.replace(stage, src); switched = True\n        recovery=initialize_layout(payload)\n        recovery.persist_state(p[\'user\'],PLUGIN,home,src,owner,False)\n        for name in (\'scripts\', \'var\', \'etc\'):\n            directory = home / name\n            require(not directory.is_symlink() or os.readlink(directory) in (\n                \'/data/minas/plugins/data/\'+p[\'user\']+\'/\'+PLUGIN+\'/\'+name,\n), \'插件数据目录异常\')\n            directory.mkdir(exist_ok=True); directory.chmod(0o700); os.chown(directory, *owner)\n        atomic(control, (payload / \'scripts/control\').read_bytes(), 0o755, owner)\n        for name, target in ((\'src\', src), (\'tmp\', tmp)):\n            if not (home / name).is_symlink(): (home / name).symlink_to(target)\n            os.lchown(home / name, *owner)\n        for directory in (home, tmp): os.chown(directory, *owner); directory.chmod(0o700)\n        now = int(time.time())\n        info = dict(plugin=PLUGIN, name=\'SSH 恢复\', id=19098, version=VERSION, tags=[\'tool\'], timestamp=now,\n                    desc=\'手动开启 SSH、恢复主机密钥与登录公钥\', developer=\'Local\', publisher=\'Local\', changelog=\'新旧固件恢复、实际登录授权诊断与无私钥离线应急包\',\n                    system=False, size=sum(f.stat().st_blocks * 512 for f in src.rglob(\'*\') if f.is_file()), port=\'\', type=\'standard\',\n                    forceupgrade=False, ext={}, hotplug=[], abstract=abstract(src))\n        atomic(home / \'INFO\', encoded(info), owner=owner)\n        if web.is_symlink(): web.unlink()\n        web.symlink_to(home / \'src/ui\')\n        os.lchown(web, *owner)\n        install_icon(payload, icon)\n        data = read_json(registry)\n        previous=data.get(PLUGIN,{})\n        enabled=previous.get(\'enable\',True)\n        if not isinstance(enabled,bool):enabled=True\n        data[PLUGIN] = dict(resource={\'mpk\':str(home/\'INFO\'),\'icon\':\'/icon/sshrecovery.icon\',\'preview\':[]}, status=previous.get(\'status\',\'running\'), install=True, upgrade=False,\n                            enable=enabled, changetime=now, icon=\'/icon/sshrecovery.icon\', progress=\'100\', frontend=read_json(src / \'ui/config\'),\n                            info=info, online=True)\n        st=registry.stat(); atomic(registry, encoded(data), st.st_mode & 0o777, (st.st_uid, st.st_gid))\n        env = dict(os.environ, PLUG_USER=p[\'user\'], PLUG_NAME=PLUGIN, PLUG_SRC_DIR=str(src), PLUG_HOME_DIR=str(home), PLUG_TMP_DIR=str(tmp), PLUG_STATUS=\'unverified\')\n        check = subprocess.run([\'runuser\',\'-u\',p[\'user\'],\'--\',\'/usr/bin/plugin.sh\', \'verify\'], env=env, capture_output=True, timeout=60)\n        require(check.returncode == 0, \'系统源码校验未通过，正在回退安装\')\n        report=system_install(p[\'user\'],payload)\n        print(\'公共权限组件：\'+report[\'helperVersion\']+\'；安装事务完成，临时回退文件已清理\')\n        tools=report[\'sshTools\']\n        print(\'SSH 恢复 \'+VERSION+\' 已安装：\' + p[\'user\'] + \'；已同步 \'+str(len(tools[\'updated\']))+\' 个已有恢复程序，保留服务启用状态及登录公钥。\')\n        if tools[\'skipped\']:print(\'保留自定义恢复程序：\'+\', \'.join(tools[\'skipped\']))\n    except BaseException:\n        st=registry.stat(); atomic(registry,old_registry,st.st_mode & 0o777,(st.st_uid,st.st_gid))\n        if not web_existed and web.is_symlink(): web.unlink()\n        if switched and src.exists(): shutil.rmtree(src)\n        if src_moved and previous_src.exists(): os.replace(previous_src, src)\n        if new_home: shutil.rmtree(home)\n        else:\n            if previous_info is not None: atomic(home/\'INFO\',previous_info,owner=owner)\n            if previous_control is not None: atomic(control,previous_control,0o755,owner)\n        if new_tmp and tmp.exists(): shutil.rmtree(tmp)\n        if old_icon is not None: atomic(icon,old_icon)\n        elif icon.exists(): icon.unlink()\n        raise\n    finally:\n        if stage.exists(): shutil.rmtree(stage)\n        if backup.exists(): shutil.rmtree(backup)\n\ndef uninstall(p):\n    home, src, tmp, registry, web = (p[k] for k in (\'home\', \'src\', \'tmp\', \'registry\', \'web\'))\n    backup = Path(\'/data/minas/backups/plugins/sshrecovery\') / p[\'user\'] / (time.strftime(\'%Y%m%d-%H%M%S\') + \'-\' + str(os.getpid()))\n    backup.mkdir(parents=True, mode=0o700)\n    for name in (\'var\',\'INFO\'):\n        path=home/name\n        require(not path.is_symlink() or os.readlink(path) == \'/data/minas/plugins/data/\' + p[\'user\'] + \'/\' + PLUGIN + \'/\' + name, \'备份对象链接异常\')\n        if path.is_dir(): shutil.copytree(path,backup/name,symlinks=True)\n        elif path.is_file(): shutil.copy2(path,backup/name)\n    shutil.copy2(registry,backup/\'plugin-list.json\')\n    # Refuse module removal before touching the UI, e.g. if another privileged\n    # operation is active. A failed permission transaction leaves the UI intact.\n    system_remove(p[\'user\'])\n    coordinator=Path(\'/data/minas/plugins/recovery/recovery.py\')\n    if coordinator.is_file():\n        subprocess.run([sys.executable,\'-B\',str(coordinator),\'forget\',\'--user\',p[\'user\'],\'--plugin\',PLUGIN],check=True)\n    data=read_json(registry);data.pop(PLUGIN,None);st=registry.stat()\n    atomic(registry,encoded(data),st.st_mode & 0o777,(st.st_uid,st.st_gid))\n    if web.is_symlink(): web.unlink()\n    for path in (src,tmp,home):\n        require(path.resolve()==path and path.name==PLUGIN, \'删除目标发生变化，已停止\')\n        if path.exists(): shutil.rmtree(path)\n    if not any(state==\'installed\' for _,state in users(\'uninstall\')): Path(\'/data/plugin/www/icon/sshrecovery.icon\').unlink(missing_ok=True)\n    print(\'SSH 恢复已卸载。插件配置备份：\' + str(backup))\n\ndef main(args):\n    require(os.geteuid()==0 and Path(\'/etc/config/plugin\').is_file(), \'请通过安装脚本以 root 连接小米智能存储\')\n    require(bool(args), \'缺少操作\')\n    action=args[0]\n    if action in (\'--scan\',\'--check\'):\n        require(len(args)>=3 and args[1]==PLUGIN and args[2] in (\'install\',\'uninstall\'), \'扫描参数无效\')\n        if action==\'--scan\':\n            for user,state in users(args[2]): print(user+\'\\t\'+state)\n        else:\n            for user in args[3:]: paths(user,args[2])\n        return\n    require(action in (\'install\',\'uninstall\') and len(args)==2, \'操作参数无效\')\n    require(bool(re.fullmatch(\'u[0-9]+\',args[1])), \'无效用户\')\n    if action==\'install\':initialize_layout(Path(__file__).resolve().parents[1])\n    with contextlib.ExitStack() as stack:\n        for path in (\'/data/plugin/.local-plugin-installer.lock\', \'/data/plugin/.\'+args[1]+\'.plugins.lock\'):\n            lock=stack.enter_context(open(path,\'a\'));fcntl.flock(lock,fcntl.LOCK_EX)\n        p=paths(args[1],action)\n        if action==\'install\': install(p,Path(__file__).resolve().parents[1])\n        else: uninstall(p)\n        if action==\'install\':\n            fcntl.flock(lock,fcntl.LOCK_UN)\n            payload=Path(__file__).resolve().parents[1]\n            subprocess.run([sys.executable,\'-B\',str(payload/\'installer/recovery/recovery.py\'),\'capture\',\'--user\',args[1],\'--plugin\',PLUGIN,\'--package\',str(payload)],check=True)\n\nif __name__==\'__main__\':\n    try: main(sys.argv[1:])\n    except Exception as exc:\n        print(\'[错误] \'+str(exc),file=sys.stderr);sys.exit(1)\n'

def run(args,check=True,**kwargs):
    p=subprocess.run([str(x) for x in args],text=True,capture_output=True,timeout=kwargs.pop('timeout',60),**kwargs)
    if check and p.returncode:raise RuntimeError((p.stderr or p.stdout).strip()[-2000:])
    return p

def load(path):
    path=Path(path)
    if path.is_symlink():raise ValueError('拒绝读取重定向的管理记录：'+str(path))
    return json.loads(path.read_text())

def below(path,base):
    return path==base or path.startswith(base.rstrip('/')+'/')

def identity(path):
    s=Path(path).lstat();return [s.st_dev,s.st_ino,s.st_mode,s.st_uid,s.st_size,s.st_mtime_ns]

def registries():
    out={}
    for f in Path('/data/plugin').glob('u*.list'):
        if not re.fullmatch(r'u[0-9]+',f.stem):continue
        out[f.stem]=load(f)
    return out

def references():
    """Read metadata and kernel references, never scan user media or cache bodies."""
    refs=[];units=[]
    for base in (Path('/etc/systemd/system'),Path('/run/systemd/system'),Path('/run/systemd/transient'),Path('/etc/cron.d'),Path('/etc/sudoers.d')):
        for p in base.rglob('*') if base.exists() else []:
            if p.is_file() and not p.is_symlink() and p.stat().st_size<200000:
                text=p.read_text(errors='replace')
                refs += [(m.group(0).rstrip("'\";,)"),str(p)) for m in re.finditer(r'/(?:data|home|nas|run|tmp)/[^\s\x00\"\'<>;]+',text)]
                if base.name in ('system','transient') and p.suffix in ('.service','.timer','.socket'):units.append(str(p))
    for proc in Path('/proc').glob('[0-9]*'):
        try:
            for key in ('cwd','exe','root'):
                refs.append((os.readlink(proc/key).removesuffix(' (deleted)'),'进程 '+proc.name))
            for arg in (proc/'cmdline').read_bytes().split(b'\0'):
                if arg.startswith(b'/') and b'\n' not in arg:refs.append((os.fsdecode(arg),'进程 '+proc.name))
            for fd in (proc/'fd').iterdir():
                try:refs.append((os.readlink(fd).removesuffix(' (deleted)'),'文件句柄 '+proc.name))
                except OSError:pass
            for line in (proc/'maps').read_text().splitlines():
                fields=line.split(None,5)
                if len(fields)==6 and fields[5].startswith('/'):refs.append((fields[5].removesuffix(' (deleted)'),'内存映射 '+proc.name))
        except (OSError,ProcessLookupError):pass
    for line in Path('/proc/self/mountinfo').read_text().splitlines():
        mount=line.split()[4].replace('\\040',' ')
        refs.append((mount,'挂载点'))
    for user in Path('/home').glob('u*'):
        if not re.fullmatch(r'u[0-9]+',user.name):continue
        for plugin in PLUGINS:
            for name in ('src','tmp','etc','var'):
                p=user/'plugin'/plugin/name
                if p.is_symlink():refs.append((os.path.abspath(os.path.join(p.parent,os.readlink(p))),str(p)))
    return refs,units

def tool_status():
    result={}
    for key,base,marker in (('ssh',ROOT/'ssh',Path('/etc/cron.d/keep-ssh')),('network',ROOT/'docker/network',Path('/etc/systemd/system/minas-docker-ipv6.service')),('docker',ROOT/'docker/runtime',Path('/etc/systemd/system/docker.service.d/80-minas-runtime.conf'))):
        transactions=[]
        for p in (base/'transactions').glob('*/state.json'):
            data=load(p);transactions.append({'id':p.parent.name,'phase':data.get('phase'),'path':str(p),'backup':data.get('backup')})
        active=marker.exists() or any(t['phase'] in ('pending','confirmed','installed','rollback-failed') for t in transactions)
        unit={'ssh':'minas.boot_check.service','network':'minas-docker-ipv6.service','docker':'docker.service'}[key]
        service=run(['systemctl','show',unit,'-p','LoadState','-p','ActiveState','--value'],False).stdout.strip().splitlines()
        result[key]={'name':{'ssh':'SSH 开机恢复','network':'Docker 网络修复','docker':'Docker 升级'}[key],'installed':active,'directory':str(base),'marker':str(marker),'service':{'name':unit,'definitionExists':marker.exists(),'state':service},'transactions':transactions,'residue':base.exists() and not active}
    return result

def scan():
    regs=registries();refs,units=references();tools=tool_status();items={};plugins=[]
    def installed(user,plugin):return bool(regs.get(user,{}).get(plugin,{}).get('install'))
    def add(path,owner,layout,reason='',keep=False,automatic=False):
        p=Path(path)
        if not os.path.lexists(p):return
        path=str(p);used=sorted({origin for target,origin in refs if below(target,path)})
        # Parents used by several installed components are never cleanup targets.
        blocked=keep or bool(used)
        status='使用中' if used or keep else '可清理遗留' if automatic else '未使用／卸载后保留'
        items[path]={'id':hashlib.sha256(path.encode()).hexdigest()[:12],'path':path,'owner':owner,'layout':layout,'status':status,'deletable':not blocked,'automatic':automatic and not blocked,'reason':reason,'references':used[:8],'identity':identity(p),'link':os.readlink(p) if p.is_symlink() else None}
    for old,new in OLD.items():
        docker_backup='docker-upgrade-backups' in old
        owner=next((t['name'] for t in tools.values() if t['directory']==new),'历史公共组件')
        add(old,'Docker 升级备份' if docker_backup else owner,'旧',keep=docker_backup,automatic=not docker_backup,reason='Docker 升级备份始终保留' if docker_backup else '')
    any_plugins=any(installed(u,p) for u in regs for p in PLUGINS)
    for path,name,used in ((ROOT/'privileged','公共权限组件',any_plugins),(ROOT/'plugins/recovery','插件恢复服务',any_plugins)):
        add(path,name,'新',keep=used,reason='仍有已安装插件依赖' if used else '')
    for key,t in tools.items():add(t['directory'],t['name'],'新',keep=t['installed'],reason='卸载恢复所需事务及运行文件' if t['installed'] else '')
    for path in ('/data/minas/backups/docker','/data/docker-upgrade-backups'):
        add(path,'Docker 升级备份','备份',keep=True,reason='用户指定保留')
    for u in sorted(set(regs)|{p.name for p in (ROOT/'plugins/data').glob('u*')}):
        if not re.fullmatch(r'u[0-9]+',u):continue
        for plugin in PLUGINS:
            home=Path('/home')/u/'plugin'/plugin;present=installed(u,plugin)
            if present:
                service=None
                if plugin in ('mihomo','quickshare','downloadcenter'):
                    name='minas-plugin-'+plugin+'-'+u+'.service'
                    report=run(['systemctl','show',name,'-p','LoadState','-p','ActiveState','-p','SubState','-p','MainPID'],False)
                    runtime=dict(x.split('=',1) for x in report.stdout.strip().splitlines() if '=' in x)
                    service={'name':name,'definitionExists':(Path('/etc/systemd/system')/name).is_file(),'runtime':runtime}
                plugins.append({'user':u,'plugin':plugin,'name':LABELS[plugin],'enabled':regs[u][plugin].get('enable'),'home':str(home),'service':service})
            add(ROOT/'plugins/data'/u/plugin,u+'/'+LABELS[plugin],'新',keep=present,reason='现用配置、任务或保护数据' if present else '卸载后的持久数据，手动选择才删除')
            add(Path('/data/.minas-plugin-data')/u/plugin,u+'/'+LABELS[plugin],'旧',automatic=True)
            add(Path('/data/.minas-privileged/modules')/plugin,LABELS[plugin]+'旧权限模块','旧',automatic=True)
            add(ROOT/'privileged/modules'/plugin,LABELS[plugin]+'权限模块','新',keep=any(installed(account,plugin) for account in regs))
            add(home,u+'/'+LABELS[plugin],'安装入口',keep=present)
            for root in Path('/nas').glob('pool[0-9]*'):
                for name in ('pluginsrc','plugintmp'):
                    add(root/u/'plugin'/name/plugin,u+'/'+LABELS[plugin],name,keep=present)
            add(Path('/data/plugin')/('.'+plugin+'-system'),'旧权限模块 '+plugin,'旧',automatic=True)
            add(Path('/data')/('.'+plugin+'-system'),'旧权限模块 '+plugin,'旧',automatic=True)
        reserve=Path('/home')/u/'plugin/.reserve'
        for p in reserve.glob('*/*'):
            if p.parent.name in PLUGINS:add(p,'自定义插件安装卸载备份','备份',automatic=True)
    add(ROOT/'plugins/mediaeditor','影视编辑旧保护数据','旧',automatic=True)
    add(ROOT/'privileged/modules/mediaeditor/var/storage-layout.json','已完成的影视迁移记录','旧',automatic=True)
    for pattern in ('.registry-before-install.*','*.before-local-*'):
        for p in Path('/data/plugin').glob(pattern):add(p,'旧注册信息备份','遗留',automatic=True)
    for path in ('backups/privileged','backups/plugins','backups/ssh-bootstrap','plugins/recovery/deployments','plugins/recovery/operations','docker/runtime/code-backups'):
        base=ROOT/path
        for p in base.iterdir() if base.is_dir() and not base.is_symlink() else []:
            pending=False
            if path=='plugins/recovery/deployments' and (p/'state.json').is_file():
                pending=load(p/'state.json').get('phase') not in ('committed','rolled-back','complete')
            add(p,'历次部署／测试备份','遗留',keep=pending,automatic=True,reason='未完成事务，保留恢复材料' if pending else '')
    migration=ROOT/'migration'
    phases=[load(p).get('phase') for p in migration.glob('transactions/*/state.json')]
    add(migration,'旧迁移工具及事务','旧',keep=any(p not in ('committed','rolled-back','complete') for p in phases),automatic=True)
    for base in ((ROOT/'plugins/recovery/records'),):
        for record in base.glob('u*-*'):
            current=(record/'current').read_text().strip() if (record/'current').is_file() else None
            for generation in record.glob('generation-*'):
                add(generation,'插件恢复副本','恢复',keep=generation.name==current,automatic=generation.name!=current,reason='当前恢复副本必须保留' if generation.name==current else '过期恢复副本')
    for path in ('/run/minas-auto-layout.lock','/run/minas-layout-docker-runtime.lock'):
        add(path,'已退役的目录迁移锁','旧',automatic=True)
    patterns=('minas-ui.*','minas-xunlei.*','minas-cleanup.*','minas-manager.*','minas-docker-upgrade.*','minas-docker-bridge.*','minas-runtime.*','minas-entry.*','minas-spec-*','minas-auto-layout-*','minas-component-*','minas-docker-probe-*','xiaomi-plugin.*','minas-ssh-transport.*')
    for parent in (Path('/run'),Path('/tmp')):
        for pattern in patterns:
            for p in parent.glob(pattern):add(p,'部署／迅雷触发／隔离测试暂存','暂存',automatic=True)
    for unit in units:
        p=Path(unit)
        if re.fullmatch(r'(?:minas-plugin-recovery(?:-watch)?|minas-data-layout-[a-z0-9]+|minas-(?:ui|xunlei|test)[a-z0-9-]*)\.(?:service|timer)',p.name):
            state=run(['systemctl','show',p.name,'-p','ActiveState','--value'],False).stdout.strip()
            add(p,'旧服务定义','服务',keep=state not in ('inactive','failed',''),automatic=True,reason='服务状态：'+state)
    return {'version':VERSION,'plugins':plugins,'tools':tools,'directories':sorted(items.values(),key=lambda x:(x['owner'],x['path']))}

def confirm(message,yes):
    print(message,flush=True)
    if not yes and (not sys.stdin.isatty() or input('输入 YES 执行：').strip()!='YES'):raise ValueError('未确认，未执行')

# FD-relative deletion never follows a symlink or traverses a filesystem boundary.
DELETE_CONTENTS='''import os,stat,sys
def clear(fd,dev):
 for name in os.listdir(fd):
  s=os.stat(name,dir_fd=fd,follow_symlinks=False)
  if stat.S_ISDIR(s.st_mode):
   child=os.open(name,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW,dir_fd=fd)
   try:
    if os.fstat(child).st_dev!=dev:raise ValueError('filesystem boundary')
    clear(child,dev)
   finally:os.close(child)
   os.rmdir(name,dir_fd=fd)
  else:os.unlink(name,dir_fd=fd)
fd=os.open('.',os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW,dir_fd=int(sys.argv[1]))
try:clear(fd,os.fstat(fd).st_dev)
finally:os.close(fd)
'''

def delete_item(item):
    p=Path(item['path']);expected=item['identity']
    if not p.is_absolute() or '..' in p.parts:raise ValueError('无效清理路径')
    with contextlib.ExitStack() as stack:
        parent=os.open('/',os.O_PATH|os.O_DIRECTORY);stack.callback(os.close,parent)
        for part in p.parts[1:-1]:
            try:parent=os.open(part,os.O_PATH|os.O_DIRECTORY|os.O_NOFOLLOW,dir_fd=parent)
            except OSError as e:raise ValueError('父目录存在链接或已改变') from e
            stack.callback(os.close,parent)
        s=os.stat(p.name,dir_fd=parent,follow_symlinks=False)
        if [s.st_dev,s.st_ino,s.st_mode,s.st_uid,s.st_size,s.st_mtime_ns]!=expected:raise ValueError('目录已变化，请重新扫描：'+str(p))
        if stat.S_ISDIR(s.st_mode):
            fd=os.open(p.name,os.O_PATH|os.O_DIRECTORY|os.O_NOFOLLOW,dir_fd=parent);stack.callback(os.close,fd)
            if os.fstat(fd).st_ino!=s.st_ino:raise ValueError('目录已变化')
            demote=None
            if s.st_uid:
                account=pwd.getpwuid(s.st_uid)
                def demote():
                    os.initgroups(account.pw_name,account.pw_gid);os.setgid(account.pw_gid);os.setuid(account.pw_uid)
            # Root opens only O_PATH; cache traversal and deletion run as its owner.
            run([sys.executable,'-B','-c',DELETE_CONTENTS,str(fd)],pass_fds=(fd,),preexec_fn=demote,timeout=300)
            current=os.stat(p.name,dir_fd=parent,follow_symlinks=False)
            if (current.st_dev,current.st_ino)!=(s.st_dev,s.st_ino):raise ValueError('入口身份变化，停止移除')
            os.rmdir(p.name,dir_fd=parent)
        else:os.unlink(p.name,dir_fd=parent)

@contextlib.contextmanager
def operation_lock():
    with contextlib.ExitStack() as stack:
        for path in ('/data/plugin/.local-plugin-installer.lock','/data/minas/privileged/component.lock'):
            if not Path(path).parent.exists():continue
            fd=os.open(path,os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW,0o600);stack.callback(os.close,fd)
            fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
        yield

def clean(ids,yes=False,automatic=False):
    with operation_lock():
        snapshot=scan();table={x['id']:x for x in snapshot['directories']}
        chosen=[x for x in table.values() if x['automatic']] if automatic else [table[i] for i in ids]
        # Selecting both parent and child removes the parent only once.
        chosen=[x for x in chosen if not any(x is not y and below(x['path'],y['path']) for y in chosen)]
        if not chosen:print('没有可清理项目。');return []
        if any(not x['deletable'] for x in chosen):raise ValueError('包含使用中或必须保留的项目，已拒绝整批操作')
        confirm('将永久删除以下目录／文件：\n'+'\n'.join(x['path'] for x in chosen),yes)
        removed=[]
        for item in chosen:
            fresh={x['id']:x for x in scan()['directories']}.get(item['id'])
            if not fresh or not fresh['deletable'] or fresh['identity']!=item['identity']:raise ValueError('状态变化，请重新检查：'+item['path'])
            delete_item(item);removed.append(item['path'])
        if any(x['layout']=='服务' for x in chosen):run(['systemctl','daemon-reload'])
        for relative in ('plugins/recovery/deployments','plugins/recovery/operations','docker/runtime/code-backups','backups/privileged','backups/plugins','backups/ssh-bootstrap'):
            container=ROOT/relative
            try:
                if not container.is_symlink() and container.stat().st_uid==0:container.rmdir()
            except (FileNotFoundError,OSError):pass
        print(json.dumps({'removed':removed},ensure_ascii=False));return removed

def uninstall(plugin,user,yes=False):
    if plugin not in PLUGINS or not re.fullmatch(r'u[0-9]+',user or ''):raise ValueError('无效插件／账号')
    if not registries().get(user,{}).get(plugin,{}).get('install'):raise ValueError('该账号未安装所选插件')
    confirm('卸载 '+user+' 的 '+LABELS[plugin]+'。停止其服务并撤销授权；保留下载内容、容器和持久数据。',yes)
    if plugin=='sshrecovery':
        with tempfile.TemporaryDirectory(prefix='minas-uninstall-',dir='/run') as d:
            p=Path(d)/'install.py';p.write_text(SSH_INSTALLER)
            run([sys.executable,'-B',p,'uninstall',user],timeout=300)
    else:
        script=UNINSTALLERS[plugin]
        result=run(['/bin/sh','-s','--',user],input=script,timeout=300);print(result.stdout)
    if registries().get(user,{}).get(plugin,{}).get('install'):raise ValueError('卸载后仍有安装登记')

def restore(tool,transaction,yes=False):
    state=tool_status()[tool]
    if tool in ('network','docker'):
        choices=[t for t in state['transactions'] if t['phase'] in ('installed','confirmed','pending','rollback-failed')]
        if transaction:choices=[t for t in choices if t['id']==transaction]
        if len(choices)!=1:raise ValueError('请指定唯一事务编号 --transaction；可先 --scan 查看')
        selected=choices[0];base=Path(state['directory'])
        worker=base/('upgrade.py' if tool=='docker' else 'repair.py')
        if worker.is_symlink() or worker.stat().st_uid!=0 or worker.stat().st_mode&0o022:raise ValueError('恢复程序权限异常')
        confirm(('Docker 升级回退会恢复升级前镜像和容器层，保留当前本地卷数据；' if tool=='docker' else '网络恢复会撤销已确认修复并恢复原 UCI、防火墙及维护服务设置；')+'会短暂停止容器并重启 Docker。事务：'+selected['id'],yes)
        cmd=[sys.executable,'-B',worker,'--rollback' if tool=='docker' else '--restore',selected['id']]
        if tool=='docker':cmd+=['--yes']
        else:cmd+=['--yes']
        print(run(cmd,timeout=1800).stdout);return
    confirm('撤销 SSH 开机恢复 Cron、开机检查挂钩和本工具的 shell 绑定；有原始 root 账户备份时恢复该账户行。保留现用登录公钥、主机密钥和当前 SSH 连接。',yes)
    with operation_lock():
        for name,marker in (('/etc/cron.d/keep-ssh','/data/minas/ssh/restore-ssh.sh'),('/etc/systemd/system/minas.boot_check.service.d/90-keep-ssh.conf','ExecStartPost=/usr/bin/systemctl start dropbear.socket'),('/etc/systemd/system/dropbear@.service.d/90-normal-shell.conf','BindReadOnlyPaths=')):
            p=Path(name)
            if not p.exists():continue
            if p.is_symlink() or p.stat().st_uid!=0 or marker not in p.read_text():raise ValueError('配置不属于本工具，拒绝覆盖：'+name)
            p.unlink()
        backup=ROOT/'ssh/passwd.before-shell-repair'
        if backup.is_file():
            old=[x for x in backup.read_text().splitlines() if x.startswith('root:')]
            if len(old)!=1 or old[0].split(':')[2]!='0':raise ValueError('root 账户备份异常')
            passwd=Path('/etc/passwd');rows=passwd.read_text().splitlines()
            if len([x for x in rows if x.startswith('root:')])!=1:raise ValueError('当前 root 账户异常')
            atomic(passwd,'\n'.join(old[0] if x.startswith('root:') else x for x in rows)+'\n',stat.S_IMODE(passwd.stat().st_mode))
        run(['systemctl','daemon-reload']);run(['systemctl','reload','crond.service'])
        print('已撤销开机恢复；当前 SSH、登录公钥和主机密钥保留。')

def atomic(path,text,mode=0o600):
    fd,name=tempfile.mkstemp(prefix='.'+path.name+'.',dir=path.parent)
    try:
        with os.fdopen(fd,'w') as f:f.write(text);f.flush();os.fchmod(f.fileno(),mode);os.fsync(f.fileno())
        os.replace(name,path)
    finally:
        if os.path.exists(name):os.unlink(name)

def display(data):
    print('\n已安装自定义插件：')
    for i,p in enumerate(data['plugins'],1):
        print(f"  P{i}  {p['user']}  {p['name']}  已安装")
        service=p.get('service')
        if service:
            runtime=service.get('runtime',{});active=runtime.get('ActiveState','unknown')
            label={'active':'运行中','inactive':'已停止','failed':'启动失败'}.get(active,'状态未知：'+active)
            print('      后台服务：'+label+'；'+('服务定义存在' if service['definitionExists'] else '服务定义已删除'))
        else:print('      页面/API 工具，无独立常驻服务')
        print('      原厂登记：'+('已启用' if p['enabled'] else '未启用')+'（独立登记标记）')
    print('\n脚本状态：')
    for key,t in data['tools'].items():print('  '+key+'  '+t['name']+'  '+('已安装' if t['installed'] else '已恢复／未安装')+'  '+', '.join(x['id']+':'+str(x['phase']) for x in t['transactions']))
    print('\n目录／文件（ID 用于选择删除；使用中项目不可删除）：')
    for x in data['directories']:
        print(f"  {x['id']}  [{x['layout']}] {x['status']}  {x['owner']}\n      {x['path']}")
        detail=x['reason'] or '；'.join(x['references'][:2])
        if detail:print('      '+detail)

def main(argv=None):
    parser=argparse.ArgumentParser(description='NAS 历史遗留检查清理、八插件卸载及三个脚本恢复；默认只读检查')
    group=parser.add_mutually_exclusive_group()
    group.add_argument('--scan',action='store_true',help='检查目录、安装登记、服务及实际引用')
    group.add_argument('--delete',nargs='+',metavar='ID',help='删除扫描中的选定 ID；拒绝使用中项目')
    group.add_argument('--clean-residue',action='store_true',help='仅清理已知且确认未使用的部署／测试遗留')
    group.add_argument('--uninstall',choices=PLUGINS,help='卸载当前账号的自定义插件')
    group.add_argument('--restore',choices=('ssh','network','docker'),help='撤销对应脚本的更改')
    parser.add_argument('--user',help='卸载账号 u数字')
    parser.add_argument('--transaction',help='网络修复／Docker 升级事务编号')
    parser.add_argument('--yes',action='store_true',help='明确确认已列明的删除／卸载／恢复')
    parser.add_argument('--json',action='store_true',help='输出检查 JSON')
    args=parser.parse_args(argv)
    if os.geteuid()!=0:raise ValueError('请在 NAS 本机以 root 运行')
    if os.readlink('/proc/self/ns/mnt')!=os.readlink('/proc/1/ns/mnt'):
        fd=os.open('/proc/1/ns/mnt',os.O_RDONLY)
        try:
            if ctypes.CDLL(None,use_errno=True).setns(fd,0):raise OSError('无法进入宿主机挂载命名空间，停止检查或清理')
        finally:os.close(fd)
    if args.delete:return clean(args.delete,args.yes)
    if args.clean_residue:return clean([],args.yes,True)
    if args.uninstall:return uninstall(args.uninstall,args.user,args.yes)
    if args.restore:return restore(args.restore,args.transaction,args.yes)
    data=scan()
    if args.json:print(json.dumps(data,ensure_ascii=False,indent=2));return
    display(data)
    if args.scan or not sys.stdin.isatty():return
    print('\n1 检查刷新  2 选择删除  3 清理已确认遗留  4 卸载插件  5 恢复脚本  0 退出')
    choice=input('请选择：').strip()
    if choice=='1':return main(['--scan'])
    if choice=='2':return clean(input('输入目录 ID（空格分隔）：').split())
    if choice=='3':return clean([],automatic=True)
    if choice=='4':
        index=int(input('输入 P 后的插件序号：'))
        if not 1<=index<=len(data['plugins']):raise ValueError('无效插件序号')
        selected=data['plugins'][index-1]
        return uninstall(selected['plugin'],selected['user'])
    if choice=='5':return restore(input('输入 ssh / network / docker：').strip(),input('事务编号（SSH 留空）：').strip() or None)
    if choice not in ('0',''):raise ValueError('无效选项')

if __name__=='__main__':
    try:main()
    except (OSError,ValueError,KeyError,IndexError,RuntimeError,subprocess.SubprocessError) as error:
        print('操作停止：'+str(error),file=sys.stderr);sys.exit(1)
